INSERT INTO `faq` (`id`, `pertanyaan`, `jawaban`, `tanggal`, `status`) VALUES
(101, 'Bagaimana cara mengajukan permohonan informasi publik?', 'Pemohon dapat mengajukan permohonan melalui kanal layanan PPID yang tersedia. Lengkapi identitas, rincian informasi yang diminta, tujuan penggunaan informasi, dan cara memperoleh informasi.', 1784379600, 1),
(102, 'Berapa lama PPID memberikan jawaban?', 'PPID memberikan pemberitahuan tertulis paling lambat 10 hari kerja sejak permohonan diterima. Jangka waktu tersebut dapat diperpanjang paling lambat 7 hari kerja dengan pemberitahuan tertulis kepada pemohon.', 1784379600, 1),
(103, 'Apa saja kategori informasi publik?', 'Informasi publik dikelompokkan menjadi informasi berkala, informasi serta-merta, informasi yang tersedia setiap saat, dan informasi yang dikecualikan sesuai ketentuan peraturan perundang-undangan.', 1784379600, 1),
(104, 'Bagaimana cara mengajukan keberatan?', 'Pemohon dapat mengajukan keberatan kepada atasan PPID apabila permohonan ditolak, informasi tidak disediakan, tanggapan terlambat, biaya tidak wajar, atau alasan lain yang diatur dalam ketentuan keterbukaan informasi publik.', 1784379600, 1),
(105, 'Di mana alamat Pemerintah Kota Batu?', 'Gedung Balaikota Among Tani, Jalan Panglima Sudirman Nomor 507, Kota Batu, Jawa Timur 65313. Telepon (0341) 591097 dan email admin@batukota.go.id.', 1784379600, 1),
(106, 'Apakah permohonan informasi dikenai biaya?', 'Layanan permohonan informasi pada dasarnya tidak dipungut biaya. Biaya penggandaan atau pengiriman, apabila ada, mengikuti kebutuhan nyata dan ketentuan yang berlaku.', 1784379600, 1);
